const item = $input.first().json;
const text = item.content;
let data;
try { data = JSON.parse(text); }
catch (e) { throw new Error('Model returned invalid JSON: ' + text); }

const CITY_TIMEZONES = {
  'los angeles': 'America/Los_Angeles',
  'seattle': 'America/Los_Angeles',
  'san francisco': 'America/Los_Angeles',
  'nyc': 'America/New_York',
  'new york': 'America/New_York',
  'atlanta': 'America/New_York',
  'miami': 'America/New_York',
  'hong kong': 'Asia/Hong_Kong',
  'beijing': 'Asia/Shanghai',
  'shanghai': 'Asia/Shanghai',
  'shenzhen': 'Asia/Shanghai',
  'tokyo': 'Asia/Tokyo',
  'seoul': 'Asia/Seoul',
  'singapore': 'Asia/Singapore',
  'amsterdam': 'Europe/Amsterdam',
  'london': 'Europe/London',
  'madrid': 'Europe/Madrid',
  'milan': 'Europe/Rome',
  'munich': 'Europe/Berlin',
  'paris': 'Europe/Paris',
};

function localDateForCity(city) {
  const tz = CITY_TIMEZONES[city.toLowerCase()];
  if (!tz) throw new Error(`No timezone mapping for city: "${city}"`);
  // en-CA locale formats as YYYY-MM-DD directly, no manual string surgery needed
  return new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date());
}

function parsePace(pace) {
  if (typeof pace === 'number') return pace;
  if (typeof pace === 'string') {
    const rangeMatch = pace.match(/(-?\+?\d+(\.\d+)?)\s*to\s*(-?\+?\d+(\.\d+)?)/i);
    if (rangeMatch) {
      const lo = parseFloat(rangeMatch[1]);
      const hi = parseFloat(rangeMatch[3]);
      return (lo + hi) / 2;
    }
    const single = parseFloat(pace);
    if (!Number.isNaN(single)) return single;
  }
  throw new Error(`Could not parse pace value: ${JSON.stringify(pace)}`);
}

const models = data.models;
const n = models.length;
let sumWeighted = 0, sumWeights = 0;
for (const m of models) {
  const paceValue = parsePace(m.pace);
  const adjustedHigh = m.high + paceValue;
  const weight = (n + 1) - m.rank;
  sumWeighted += adjustedHigh * weight;
  sumWeights += weight;
}
const weightedAvg = Math.round((sumWeighted / sumWeights) * 10) / 10;

return [{
  json: {
    city: data.city,
    pacing_time: data.pacing_time,
    unit: data.unit,
    weighted_avg: weightedAvg,
    date: localDateForCity(data.city),
  }
}];

const calc = $('Code in JavaScript').item.json;
const rows = $('Get row(s)').all();

const existing = rows[0]?.json?.history ?? null;
const timeFormatted = calc.pacing_time.toLowerCase().replace(' ', '');
const newEntry = `${calc.weighted_avg}${calc.unit} (${timeFormatted})`;

let history;
if (!existing) {
  history = newEntry;
} else {
  // case-insensitive match for an entry at this same pacing time, with or without a price already appended
  const entryRegex = new RegExp(`[\\d.]+${calc.unit}\\s*\\(${timeFormatted}[^)]*\\)`, 'i');
  if (entryRegex.test(existing)) {
    history = existing.replace(entryRegex, newEntry); // overwrite that slot, don't duplicate
  } else {
    history = `${existing} -> ${newEntry}`; // genuinely new time, append
  }
}

return [{
  json: {
    city: calc.city,
    date: calc.date,
    history,
    unit: calc.unit,
  }
}];

const calc = $('Code in JavaScript').item.json;

const citySlug = calc.city.toLowerCase().replace(/\s+/g, '-');

const [year, month, day] = calc.date.split('-');
const monthNames = ['january','february','march','april','may','june','july','august','september','october','november','december'];
