const item = $input.first().json;
const event = Array.isArray(item) ? item[0] : item;
const calc = $('build event slug').item.json;
const weightedAvg = calc.weighted_avg;
const floor = Math.floor(weightedAvg);
const decimal = weightedAvg - floor;
const rounded = decimal >= 0.8 ? floor + 1 : floor;

// threshold below which a "Yes" price is considered dead/invalid (temp has moved past this bracket)
const INVALID_PRICE_THRESHOLD = 0.01; // 1 cent

// parses a bracket title into a normalized shape:
// { type: 'below' | 'above' | 'range' | 'exact', low, high } — low/high used for matching + sorting
function parseBracket(market) {
  const title = market.groupItemTitle;

  if (title.includes('or below')) {
    const num = parseInt(title.match(/-?\d+/)[0], 10);
    return { type: 'below', low: -Infinity, high: num };
  }
  if (title.includes('or higher')) {
    const num = parseInt(title.match(/-?\d+/)[0], 10);
    return { type: 'above', low: num, high: Infinity };
  }

  // ranged bracket, e.g. "68-69°F"
  const rangeMatch = title.match(/(\d+)\s*-\s*(\d+)/);
  if (rangeMatch) {
    const low = parseInt(rangeMatch[1], 10);
    const high = parseInt(rangeMatch[2], 10);
    return { type: 'range', low, high };
  }

  // single-number bracket, e.g. "30°C"
  const num = parseInt(title.match(/-?\d+/)[0], 10);
  return { type: 'exact', low: num, high: num };
}

function bracketMatches(bracket, value) {
  switch (bracket.type) {
    case 'below': return value <= bracket.high;
    case 'above': return value >= bracket.low;
    case 'range': return value >= bracket.low && value <= bracket.high;
    case 'exact': return value === bracket.low;
  }
}

function getYesPrice(market) {
  const clobTokenIds = JSON.parse(market.clobTokenIds);
  const outcomes = JSON.parse(market.outcomes);
  const outcomePrices = JSON.parse(market.outcomePrices);
  const yesIndex = outcomes.indexOf('Yes');
  if (yesIndex === -1) throw new Error(`No "Yes" outcome found in market: ${market.question}`);
  return {
    yesPrice: parseFloat(outcomePrices[yesIndex]),
    yesTokenId: clobTokenIds[yesIndex],
  };
}

let matched = null;
for (const market of event.markets) {
  const bracket = parseBracket(market);
  if (bracketMatches(bracket, rounded)) { matched = market; break; }
}
if (!matched) throw new Error(`No bracket matched ${weightedAvg} (rounded ${rounded}) in ${event.title}`);

let { yesPrice, yesTokenId } = getYesPrice(matched);
let bumped = false;

// if the matched bracket's price is dead, the real temp has moved past it —
// walk up to the next higher bracket(s) until we find a live price
if (yesPrice < INVALID_PRICE_THRESHOLD) {
  const sorted = [...event.markets].sort((a, b) => parseBracket(a).low - parseBracket(b).low);
  const matchedLow = parseBracket(matched).low;
  const startIdx = sorted.findIndex(m => m.groupItemTitle === matched.groupItemTitle);

  for (let i = startIdx + 1; i < sorted.length; i++) {
    const candidate = sorted[i];
    const { yesPrice: candPrice, yesTokenId: candTokenId } = getYesPrice(candidate);
    if (candPrice >= INVALID_PRICE_THRESHOLD) {
      matched = candidate;
      yesPrice = candPrice;
      yesTokenId = candTokenId;
      bumped = true;
      break;
    }
  }
}

// --- patch the saved history entry for this pacing_time with the price ---
const savedRow = $('Upsert row(s)').item.json;
const timeFormatted = calc.pacing_time.toLowerCase().replace(' ', '');
const priceTag = `${timeFormatted}, ${Math.round(yesPrice * 100)}¢${bumped ? '↑' : ''}`;
const bareRegex = new RegExp(`\\(${timeFormatted}\\)`, 'i');
const updatedHistory = (savedRow.history ?? '').replace(bareRegex, `(${priceTag})`);

return [{
  json: {
    city: calc.city,
    date: calc.date,
    unit: calc.unit,
    history: updatedHistory,
    bracket: matched.groupItemTitle,
    yes_token_id: yesTokenId,
    yes_price: yesPrice,
    yes_price_cents: Math.round(yesPrice * 100),
  }
}];

const calc = $('Code in JavaScript2').item.json; // has city, date, history, bracket, yes_price_cents

if (calc.yes_price_cents >= 99.95) {
  return [];
}

const historyStr = calc.history;
const entries = [];
const regex = /([\d.]+)([CF])\s*\(([^,)]+)(?:,\s*(\d+)¢)?\)/g;
let match;
while ((match = regex.exec(historyStr)) !== null) {
  entries.push({
    value: parseFloat(match[1]),
    unit: match[2],
    time: match[3].trim(),
    price: match[4] ? `${match[4]}¢` : '—',
  });
}
const lines = entries.map((e, i) => {
  let arrow = '  ';
  if (i > 0) {
    if (e.value > entries[i - 1].value) arrow = '↑ ';
    else if (e.value < entries[i - 1].value) arrow = '↓ ';
    else arrow = '→ ';
  }
  return `${e.time.padEnd(8)}${(e.value + e.unit).padEnd(7)}${arrow}${e.price}`;
});
const cityName = calc.city.charAt(0).toUpperCase() + calc.city.slice(1);
const message = `**${cityName} — ${calc.date}**\nBracket: ${calc.bracket} (currently ${calc.yes_price_cents}¢)\n\`\`\`\n${lines.join('\n')}\n\`\`\``;
return [{ json: { message } }];

